import{_ as e,o as a,c as l,a2 as s}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"MCP Tools Specification","description":"","frontmatter":{},"headers":[],"relativePath":"reference/mcp-tools.md","filePath":"reference/mcp-tools.md","lastUpdated":1786221059000}'),i={name:"reference/mcp-tools.md"};function o(d,t,n,r,c,h){return a(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="mcp-tools-specification" tabindex="-1">MCP Tools Specification <a class="header-anchor" href="#mcp-tools-specification" aria-label="Permalink to &quot;MCP Tools Specification&quot;">​</a></h1><p>Chanakya MCP exposes <strong>fourteen schema-validated tools</strong> over standard JSON-RPC 2.0 stdio. Every tool strictly validates its arguments with a Zod schema that doubles as its published JSON Schema.</p><div class="custom-banner"><div class="custom-banner-icon">ðŸ› ï¸</div><div class="custom-banner-content"><h4>14 Production MCP Tools</h4><p>11 Read-Only structural query tools and 3 Safe Edit mutation tools designed specifically for AI coding agents.</p></div></div><hr><h2 id="tool-category-overview" tabindex="-1">Tool Category Overview <a class="header-anchor" href="#tool-category-overview" aria-label="Permalink to &quot;Tool Category Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Category</th><th style="text-align:left;">Tools</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Search (2)</strong></td><td style="text-align:left;"><code>search_symbols</code>, <code>search_code</code></td><td style="text-align:left;">Sub-millisecond symbol name lookup and ReDoS-isolated fulltext search.</td></tr><tr><td style="text-align:left;"><strong>Navigation (5)</strong></td><td style="text-align:left;"><code>get_symbol</code>, <code>get_file_structure</code>, <code>find_definition</code>, <code>find_references</code>, <code>get_callers</code>, <code>get_callees</code></td><td style="text-align:left;">AST hierarchy, callers, callees, definitions, and cross-file references.</td></tr><tr><td style="text-align:left;"><strong>Context (1)</strong></td><td style="text-align:left;"><code>get_symbol_context</code></td><td style="text-align:left;">Comprehensive 360-degree context for a symbol in a single tool call.</td></tr><tr><td style="text-align:left;"><strong>Module Graph (2)</strong></td><td style="text-align:left;"><code>get_dependencies</code>, <code>get_dependents</code></td><td style="text-align:left;">Project-wide import/export graph, external npm packages, and barrel files.</td></tr><tr><td style="text-align:left;"><strong>Safe Edits (3)</strong></td><td style="text-align:left;"><code>apply_patch</code>, <code>replace_symbol</code>, <code>rename_symbol</code></td><td style="text-align:left;">Atomic, verified file modifications with automatic incremental reindexing.</td></tr></tbody></table><hr><h2 id="_1-search-tools" tabindex="-1">1. Search Tools <a class="header-anchor" href="#_1-search-tools" aria-label="Permalink to &quot;1. Search Tools&quot;">​</a></h2><h3 id="search-symbols" tabindex="-1"><code>search_symbols</code> <a class="header-anchor" href="#search-symbols" aria-label="Permalink to &quot;`search_symbols`&quot;">​</a></h3><p>Finds declarations across the project by name with prioritized exact, prefix, and substring ranking.</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Type</th><th style="text-align:left;">Required</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>query</code></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;"><strong>Yes</strong></td><td style="text-align:left;">Symbol name or query substring.</td></tr><tr><td style="text-align:left;"><code>match</code></td><td style="text-align:left;"><code>&quot;exact&quot; | &quot;prefix&quot; | &quot;substring&quot;</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Ranking match strategy (defaults to ranked sequence).</td></tr><tr><td style="text-align:left;"><code>kinds</code></td><td style="text-align:left;"><code>SymbolKind[]</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Restrict to specific kinds (<code>function</code>, <code>class</code>, <code>interface</code>, etc.).</td></tr><tr><td style="text-align:left;"><code>languages</code></td><td style="text-align:left;"><code>LanguageId[]</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Restrict to <code>javascript</code>, <code>jsx</code>, <code>typescript</code>, or <code>tsx</code>.</td></tr><tr><td style="text-align:left;"><code>path_contains</code></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Substring filter on POSIX file path.</td></tr><tr><td style="text-align:left;"><code>exported_only</code></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Restrict to public module exports.</td></tr><tr><td style="text-align:left;"><code>exclude_ambient</code></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Drop <code>.d.ts</code> and ambient declarations.</td></tr><tr><td style="text-align:left;"><code>limit</code></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Maximum returned symbols (1â€“500, default: 50).</td></tr></tbody></table><hr><h3 id="search-code" tabindex="-1"><code>search_code</code> <a class="header-anchor" href="#search-code" aria-label="Permalink to &quot;`search_code`&quot;">​</a></h3><p>Searches file contents for literal strings or regex patterns, annotating every match with its innermost enclosing AST symbol.</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Type</th><th style="text-align:left;">Required</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>query</code></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;"><strong>Yes</strong></td><td style="text-align:left;">Search pattern or text string.</td></tr><tr><td style="text-align:left;"><code>is_regex</code></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">No</td><td style="text-align:left;">When <code>true</code>, evaluates query as regular expression.</td></tr><tr><td style="text-align:left;"><code>case_sensitive</code></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Case sensitivity flag (default: <code>false</code>).</td></tr><tr><td style="text-align:left;"><code>languages</code></td><td style="text-align:left;"><code>LanguageId[]</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Filter by file languages.</td></tr><tr><td style="text-align:left;"><code>path_contains</code></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Substring path filter.</td></tr><tr><td style="text-align:left;"><code>limit</code></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Total match limit (1â€“500, default: 100).</td></tr><tr><td style="text-align:left;"><code>max_matches_per_file</code></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Max matches per individual file.</td></tr><tr><td style="text-align:left;"><code>context_lines</code></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Number of surrounding lines to return (0â€“10).</td></tr><tr><td style="text-align:left;"><code>time_budget_ms</code></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;">No</td><td style="text-align:left;">Worker execution timeout (default: 500ms).</td></tr></tbody></table><hr><h2 id="_2-navigation-context-tools" tabindex="-1">2. Navigation &amp; Context Tools <a class="header-anchor" href="#_2-navigation-context-tools" aria-label="Permalink to &quot;2. Navigation &amp; Context Tools&quot;">​</a></h2><h3 id="get-symbol" tabindex="-1"><code>get_symbol</code> <a class="header-anchor" href="#get-symbol" aria-label="Permalink to &quot;`get_symbol`&quot;">​</a></h3><p>Retrieves full metadata for a given symbol ID.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Example Response:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/services/user.ts#class:UserService&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UserService&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;class&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;file_path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/services/user.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;start_line&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">14</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;end_line&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">86</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;signature&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;export class UserService implements IUserService&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;export_kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;named&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h3 id="get-symbol-context" tabindex="-1"><code>get_symbol_context</code> <a class="header-anchor" href="#get-symbol-context" aria-label="Permalink to &quot;`get_symbol_context`&quot;">​</a></h3><p>Provides a complete 360-degree context for a symbol in a single tool call:</p><ul><li><strong>Declaration:</strong> Location, signature, docstrings.</li><li><strong>Hierarchy:</strong> Parent class/module and child member methods.</li><li><strong>Call Graph:</strong> Who calls this symbol (<code>callers</code>) and what it invokes (<code>callees</code>).</li><li><strong>References:</strong> Semantic occurrences across the repository.</li><li><strong>Neighborhood:</strong> Module imports and dependents.</li></ul><hr><h3 id="get-file-structure" tabindex="-1"><code>get_file_structure</code> <a class="header-anchor" href="#get-file-structure" aria-label="Permalink to &quot;`get_file_structure`&quot;">​</a></h3><p>Returns the symbol tree of a file: top-level declarations with their nested member methods and properties.</p><hr><h3 id="find-definition-find-references" tabindex="-1"><code>find_definition</code> &amp; <code>find_references</code> <a class="header-anchor" href="#find-definition-find-references" aria-label="Permalink to &quot;`find_definition` &amp; `find_references`&quot;">​</a></h3><ul><li><code>find_definition</code>: Exact file path and line coordinates where a symbol is declared.</li><li><code>find_references</code>: All semantic occurrences of a symbol across the project.</li></ul><hr><h3 id="get-callers-get-callees" tabindex="-1"><code>get_callers</code> &amp; <code>get_callees</code> <a class="header-anchor" href="#get-callers-get-callees" aria-label="Permalink to &quot;`get_callers` &amp; `get_callees`&quot;">​</a></h3><ul><li><code>get_callers</code>: Functions/methods that invoke the target symbol, annotated with confidence (<code>certain</code> vs <code>resolved</code>).</li><li><code>get_callees</code>: Functions and constructors invoked from inside the symbol body.</li></ul><hr><h2 id="_3-module-graph-tools" tabindex="-1">3. Module Graph Tools <a class="header-anchor" href="#_3-module-graph-tools" aria-label="Permalink to &quot;3. Module Graph Tools&quot;">​</a></h2><h3 id="get-dependencies" tabindex="-1"><code>get_dependencies</code> <a class="header-anchor" href="#get-dependencies" aria-label="Permalink to &quot;`get_dependencies`&quot;">​</a></h3><p>Returns all files and external npm packages imported by a file, categorized by target.</p><h3 id="get-dependents" tabindex="-1"><code>get_dependents</code> <a class="header-anchor" href="#get-dependents" aria-label="Permalink to &quot;`get_dependents`&quot;">​</a></h3><p>Returns all internal files and re-exporting barrel files (<code>export * from &#39;./mod&#39;</code>) that import the target file.</p><hr><h2 id="_4-safe-edit-tools" tabindex="-1">4. Safe Edit Tools <a class="header-anchor" href="#_4-safe-edit-tools" aria-label="Permalink to &quot;4. Safe Edit Tools&quot;">​</a></h2><h3 id="apply-patch" tabindex="-1"><code>apply_patch</code> <a class="header-anchor" href="#apply-patch" aria-label="Permalink to &quot;`apply_patch`&quot;">​</a></h3><p>Applies exact ordered string replacements to a file. Refuses patches if the target text does not match or matches more than once.</p><h3 id="replace-symbol" tabindex="-1"><code>replace_symbol</code> <a class="header-anchor" href="#replace-symbol" aria-label="Permalink to &quot;`replace_symbol`&quot;">​</a></h3><p>Slices directly into a symbol declaration using index-recorded UTF-16 code unit offsets, completely replacing its source.</p><h3 id="rename-symbol" tabindex="-1"><code>rename_symbol</code> <a class="header-anchor" href="#rename-symbol" aria-label="Permalink to &quot;`rename_symbol`&quot;">​</a></h3><p>Performs atomic, cross-file refactoring: updates the declaration, all resolved reference occurrences, and import/export bindings.</p>',49)])])}const f=e(i,[["render",o]]);export{p as __pageData,f as default};
